export function zeroBasedCheck(
  incomeEnvelopes: readonly IncomeEnvelope[],
  allocationsByEnv: ReadonlyMap<string, number>,
): ZeroBasedState {
  const budgetedIncomeCents = incomeEnvelopes.reduce((s, i) => s + i.budgetedCents, 0);
