export function WhereTheMoneyGoes({ rows }: { rows: readonly EnvelopeRow[] }) {
  const data: MoneyDatum[] = React.useMemo(() => {
    const roots = rows.filter((r) => r.depth === 0 && r.active && r.allocationCents > 0);
    const totalBudgeted = roots.reduce((s, r) => s + r.allocationCents, 0);
    return roots
      .map((r) => ({
        id: r.id,
        name: r.name,
        budgeted: r.allocationCents,
        spent: spentOf(r),
        total: r.totalCents,
        share: totalBudgeted > 0 ? r.allocationCents / totalBudgeted : 0,
      }))
      .sort((a, b) => b.budgeted - a.budgeted)
      .slice(0, 12);
  }, [rows]);

  const height = Math.max(180, data.length * 34 + 24);

  const renderTip = (props: RechartsTooltipProps) => {
    if (!props.active || !props.payload || props.payload.length === 0) return null;
    const d = props.payload[0]?.payload as MoneyDatum | undefined;
    if (!d) return null;
    const pct = d.total > 0 ? Math.round((d.spent / d.total) * 100) : 0;
    return (
      <TooltipCard
        heading={d.name}
        rows={[
          { label: "Budgeted", value: moneyFull(d.budgeted), color: CHART.brand },
          { label: "Spent", value: moneyFull(d.spent) },
          { label: "Used", value: `${pct}%` },
        ]}
      />
    );
  };

  return (
    <ChartFrame
      title="Where the money goes"
      subtitle="Top envelopes by allocation, coloured by how much is used"
      height={height}
      empty={data.length === 0}
      emptyLabel="No allocations to chart yet."
    >
      <BarChart data={data} layout="vertical" margin={{ top: 4, right: 16, bottom: 4, left: 4 }}>
        <CartesianGrid strokeDasharray="3 3" stroke={CHART.grid} horizontal={false} />
        <XAxis
          type="number"
          tickFormatter={moneyShort}
          tick={{ fontSize: 11, fill: CHART.axis }}
          tickLine={false}
          axisLine={{ stroke: CHART.grid }}
        />
        <YAxis
