export function ChartFrame({
  title,
  subtitle,
  height = 248,
  empty,
  emptyLabel = "No data to chart yet.",
  action,
  footer,
  children,
}: {
  title: string;
  subtitle?: string;
  height?: number;
  empty?: boolean;
  emptyLabel?: string;
  action?: React.ReactNode;
  footer?: React.ReactNode;
  children: React.ReactElement;
}) {
  return (
    <section className="rounded-lg border bg-card p-3 md:p-4">
      <header className="mb-3 flex items-start justify-between gap-3">
        <div className="min-w-0">
          <h3 className="truncate text-sm font-semibold tracking-tight">{title}</h3>
          {subtitle && <p className="mt-0.5 text-xs text-muted-foreground">{subtitle}</p>}
        </div>
        {action && <div className="shrink-0">{action}</div>}
      </header>
      {empty ? (
        <div
          className="flex items-center justify-center rounded-md border border-dashed text-center text-sm text-muted-foreground"
          style={{ height }}
        >
          {emptyLabel}
        </div>
      ) : (
        <div style={{ width: "100%", height }}>
          <ResponsiveContainer width="100%" height="100%">
            {children}
          </ResponsiveContainer>
        </div>
      )}
      {footer && <div className="mt-3 text-xs text-muted-foreground">{footer}</div>}
    </section>
  );
}
