import { useCarryoverHistory } from "@/lib/queries";
import { cn, formatCents } from "@/lib/utils";
import { useIsMobile } from "@/lib/useMediaQuery";
import { useDismissable } from "@/lib/useDismissable";
import { useAnchoredPosition } from "@/lib/useAnchoredPosition";

/**
 * Contributing-transactions drill-down (ISC-35, ISC-78). Clicking an envelope's
 * spent/actual figure lists the real transactions behind that figure for the
 * envelope in the current period. Data is the live transactions endpoint, never
 * invented (ISC-83); the list is newest-first as the contract returns it.
 *
 * The envelope's manual carryover adjustments (carryover.reset events, from the
 * shared history query) are interleaved into the same chronological list as
 * visually distinct, muted context rows — real events, never spend, so they
 * contribute nothing to the header total.
 *
 * Delivery is responsive: a cursor-anchored popover on desktop (pointer present)
 * and a bottom sheet on touch viewports, where a floating card anchored to a
 * non-existent cursor is the wrong idiom. Both close on Escape and backdrop/
 * outside click.
 */
export interface PopoverAnchor {
  readonly envelopeId: string;
  readonly envelopeName: string;
  readonly from: string;
  readonly to: string;
  readonly x: number;
  readonly y: number;
}

/** One row of the merged chronology: a real transaction or a carryover event. */
type LedgerRow =
  | { readonly kind: "txn"; readonly date: string; readonly txn: TransactionListItem }
  | { readonly kind: "carryover"; readonly date: string; readonly event: CarryoverHistoryEntry };

/**
 * Interleave the transactions (newest-first, by `date`) with the envelope's
 * in-period carryover.reset events (by `on`) into one newest-first chronology.
 * On a shared date, transactions come first (they are the primary content);
 * ties between carryover events fall back to the append timestamp.
